def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int | None:
        if token and all("0" <= c <= "9" for c in token):
            return int(token)
        return None

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False

        if verb == "open" and len(parts) == 3:
            name, amount = parts[1], parse_amount(parts[2])
            if amount is not None and name not in balances:
                balances[name] = amount
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, amount = parts[1], parse_amount(parts[2])
            if amount is not None and amount > 0 and name in balances:
                balances[name] += amount
                history.append(("deposit", name, amount))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, amount = parts[1], parse_amount(parts[2])
            if (
                amount is not None
                and amount > 0
                and name in balances
                and name not in frozen
                and balances[name] >= amount
            ):
                balances[name] -= amount
                history.append(("withdraw", name, amount))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            src, dst, amount = parts[1], parts[2], parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1 and history:
            rec = history.pop()
            kind = rec[0]
            if kind == "open":
                del balances[rec[1]]
                frozen.discard(rec[1])
            elif kind == "deposit":
                balances[rec[1]] -= rec[2]
            elif kind == "withdraw":
                balances[rec[1]] += rec[2]
            elif kind == "transfer":
                balances[rec[1]] += rec[3]
                balances[rec[2]] -= rec[3]
            elif kind == "freeze":
                frozen.remove(rec[1])
            elif kind == "unfreeze":
                frozen.add(rec[1])
            ok = True

        if not ok:
            rejected.append(i)

    return balances, rejected
